//! Final-gate local preparation and approved-source cursor fixtures; no mail/provider IO.
async fn execution_prepare_one(c:&mut PgConnection)->Result<bool>{let packets=packet_settings();let answers=answer_settings();let resumes=automated_apply_agents::private_resume::Settings::from_values(&host_values()).unwrap();automated_apply_agents::execution::preparation::prepare_one(c,automated_apply_agents::execution::preparation::Services{packets:&packets,answers:&answers,resumes:&resumes}).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_idle_preparation_avoids_the_owner_lock_and_does_not_touch_inspection_backlog(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let _=execution_enqueue(&mut c,"123456789012").await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut tx=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *tx).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert!(!execution_prepare_one(&mut c).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);tx.rollback().await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_saved_alert_cursors_take_ten_rows_and_ignore_other_accounts_without_copying_mail(){
    let mut c=browser_fixture().await;let mut config=execution_running(&mut c).await;config["policy"]["platforms"]["naukri"]["sources"]=json!(["approved_gmail_alerts"]);browser_save(&mut c,"application_queue_policy",config).await;
    for i in 0..12 {browser_save(&mut c,&format!("nau_alert:{i:02}"),json!({"source":if i==2{"deferred_other_platform"}else{"gmail_job_alerts"},"account_id":if i==1{"other-account"}else{"local:1"},"url":format!("https://www.naukri.com/job-listings-fictional-1234567890{i:02}"),"private_body":"PRIVATE_MAIL_BODY_CANARY"})).await;}
    assert_eq!(automated_apply_agents::execution::preparation::seed_saved_sources(&mut c).await.unwrap(),8);assert_eq!(browser_pref(&mut c,"apply_source:approved_gmail_alerts").await["id"],"nau_alert:09");assert_eq!(automated_apply_agents::execution::preparation::seed_saved_sources(&mut c).await.unwrap(),2);assert_eq!(automated_apply_agents::execution::preparation::seed_saved_sources(&mut c).await.unwrap(),0);let works:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'apply_work:')").fetch_all(&mut c).await.unwrap();assert_eq!(works.len(),10);assert!(works.iter().all(|w|!w.to_string().contains("PRIVATE_MAIL_BODY_CANARY")));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'nau_alert:')").fetch_one(&mut c).await.unwrap(),12);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_saved_source_backpressure_leaves_the_unconsumed_record_behind_its_cursor(){
    let mut c=browser_fixture().await;let mut config=execution_running(&mut c).await;config["policy"]["max_pending"]=json!(1);config["policy"]["platforms"]["naukri"]["sources"]=json!(["approved_gmail_alerts"]);browser_save(&mut c,"application_queue_policy",config.clone()).await;for i in 0..3{browser_save(&mut c,&format!("nau_alert:{i:02}"),json!({"source":"gmail_job_alerts","account_id":"local:1","url":format!("https://www.naukri.com/job-listings-fictional-1234567890{i:02}")})).await;}
    assert_eq!(automated_apply_agents::execution::preparation::seed_saved_sources(&mut c).await.unwrap(),1);let first=browser_pref(&mut c,"apply_source:approved_gmail_alerts").await;assert_eq!(first["id"],"nau_alert:00");assert_eq!(automated_apply_agents::execution::preparation::seed_saved_sources(&mut c).await.unwrap(),0);assert_eq!(browser_pref(&mut c,"apply_source:approved_gmail_alerts").await,first);config["policy"]["max_pending"]=json!(2);browser_save(&mut c,"application_queue_policy",config).await;assert_eq!(automated_apply_agents::execution::preparation::seed_saved_sources(&mut c).await.unwrap(),1);assert_eq!(browser_pref(&mut c,"apply_source:approved_gmail_alerts").await["id"],"nau_alert:01");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_preparation_creates_a_factual_packet_under_current_material_locks_then_holds_missing_resume(){
    let(mut c,job)=packet_service_fixture().await;execution_running(&mut c).await;let profile:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM candidate_profiles p WHERE singleton_key='primary'").fetch_one(&mut c).await.unwrap();browser_save(&mut c,"phase1_profile_confirmation",json!({"profile_id":profile["id"],"profile_version":profile["version"],"confirmed_at":"2026-11-16T00:00:00Z"})).await;
    sqlx::query("UPDATE jobs SET discovery_metadata=discovery_metadata||'{\"experience_min_years\":0,\"experience_max_years\":1}'::jsonb WHERE id=$1").bind(job).execute(&mut c).await.unwrap();sqlx::query("UPDATE candidate_resources SET user_confirmed=false WHERE candidate_profile_id=$1 AND resource_type='resume'").bind(profile["id"].as_str().unwrap().parse::<Uuid>().unwrap()).execute(&mut c).await.unwrap();let mut work=execution_enqueue(&mut c,"123456789012").await;let day:String=sqlx::query_scalar("SELECT to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD')").fetch_one(&mut c).await.unwrap();work["operation"]=json!("prepare");work["job_id"]=json!(job);work["facts"]=json!({"posted_date":day,"applicants_min":20,"applicants_max":20});let key=format!("apply_work:{}",work["id"].as_str().unwrap());browser_save(&mut c,&key,work).await;
    assert!(execution_prepare_one(&mut c).await.unwrap());let saved=browser_pref(&mut c,&key).await;assert_eq!(saved["stage"],"NEEDS_INPUT");assert_eq!(saved["reason"],"confirmed_primary_resume_required");assert!(saved["packet_id"].as_str().unwrap().parse::<Uuid>().is_ok());assert!(saved["lease_token"].is_null());assert_eq!(saved["admitted_actions"],json!([]));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets").fetch_one(&mut c).await.unwrap(),1);assert!(!execution_prepare_one(&mut c).await.unwrap());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_preparation_waiting_snapshot_cannot_cross_a_legacy_committed_stop(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let mut work=execution_enqueue(&mut c,"123456789012").await;work["operation"]=json!("prepare");let key=format!("apply_work:{}",work["id"].as_str().unwrap());browser_save(&mut c,&key,work.clone()).await;let mut owner=connection().await;let mut held=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();
    let mut preparing=connection().await;sqlx::query("SET application_name='fixture_prepare_owner_wait'").execute(&mut preparing).await.unwrap();let task=tokio::spawn(async move {execution_prepare_one(&mut preparing).await});let mut waiting=false;
    for _ in 0..200 {waiting=sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE application_name='fixture_prepare_owner_wait' AND wait_event_type='Lock')").fetch_one(&mut c).await.unwrap();if waiting{break;}tokio::time::sleep(std::time::Duration::from_millis(10)).await;}
    assert!(waiting,"fictional preparation must be waiting at the owner row before Stop commits");sqlx::query("UPDATE owner_preferences SET value=jsonb_set(jsonb_set(value,'{state}','\"STOPPED\"'),'{revision}','163') WHERE key='application_queue_policy'").execute(&mut *held).await.unwrap();held.commit().await.unwrap();assert_eq!(tokio::time::timeout(std::time::Duration::from_secs(3),task).await.unwrap().unwrap().unwrap_err(),Failure("execution_database_error"));assert_eq!(browser_pref(&mut c,&key).await,work);assert_eq!(browser_pref(&mut c,"application_queue_policy").await["state"],"STOPPED");
}
